import pandas as pd
import numpy as np
import torch
from torch.utils.data import Dataset, DataLoader

class RecommendationDataset(Dataset):
    def __init__(self, ratings_file):
        # Load ratings data
        self.ratings_df = pd.read_csv(ratings_file)

        # Create mappings for user and item IDs to tensor indices
        self.user_ids = self.ratings_df['user_id'].unique()
        self.item_ids = self.ratings_df['item_id'].unique()

        self.user_map = {user_id: idx for idx, user_id in enumerate(self.user_ids)}
        self.item_map = {item_id: idx for idx, item_id in enumerate(self.item_ids)}

        # Convert ratings to proper format
        self.user_indices = [self.user_map[user_id] for user_id in self.ratings_df['user_id']]
        self.item_indices = [self.item_map[item_id] for item_id in self.ratings_df['item_id']]
        self.ratings = self.ratings_df['rating'].values

    def __len__(self):
        return len(self.ratings_df)

    def __getitem__(self, idx):
        return {
            'user': torch.tensor(self.user_indices[idx], dtype=torch.long),
            'item': torch.tensor(self.item_indices[idx], dtype=torch.long),
            'rating': torch.tensor(self.ratings[idx], dtype=torch.float)
        }

    def get_n_users(self):
        return len(self.user_ids)

    def get_n_items(self):
        return len(self.item_ids)

    def get_user_id(self, index):
        return self.user_ids[index]

    def get_item_id(self, index):
        return self.item_ids[index]

def create_data_loaders(dataset, batch_size=64, train_ratio=0.8):
    # Split into train and validation
    dataset_size = len(dataset)
    indices = list(range(dataset_size))
    split = int(np.floor(train_ratio * dataset_size))

    # Shuffle indices
    np.random.shuffle(indices)

    train_indices, val_indices = indices[:split], indices[split:]

    # Create data loaders
    train_loader = DataLoader(
        dataset, batch_size=batch_size,
        sampler=torch.utils.data.SubsetRandomSampler(train_indices)
    )

    val_loader = DataLoader(
        dataset, batch_size=batch_size,
        sampler=torch.utils.data.SubsetRandomSampler(val_indices)
    )

    return train_loader, val_loader
